import { createSdkMcpServer, query, tool } from "@anthropic-ai/claude-agent-sdk";

if (typeof query !== "function") {
  throw new Error("Expected query export");
}
const ping = tool("ping", "Return pong", {}, async () => ({
  content: [{ type: "text", text: "pong" }],
}));
const server = createSdkMcpServer({
  name: "docrun-check",
  version: "0.1.0",
  tools: [ping],
});
if (!server || server.name !== "docrun-check") {
  throw new Error("Expected configured MCP server");
}
console.log("claude-agent-sdk-ready");
